import json

def replace_or_warn(path, old, new, label):
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()
    if old not in content:
        print(f"AVISO NO ENCONTRADO en {path}: {label}")
        print("   -> Este paso NO se aplico. Pega este aviso a Claude.")
        return False
    content = content.replace(old, new, 1)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"OK {path}: {label}")
    return True

def insert_before_or_warn(path, anchor, new, label):
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()
    if anchor not in content:
        print(f"AVISO NO ENCONTRADO en {path}: {label}")
        return False
    if new.strip() in content:
        print(f"YA APLICADO antes: {label}")
        return True
    content = content.replace(anchor, new + anchor, 1)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"OK {path}: {label}")
    return True


